#!/usr/bin/env bash
# Consume scripts/bench_jobs.txt rows generated by compile_sweep.py and run them
# on the local host. This is intentionally a small local orchestrator: scheduling
# across machines belongs to the operator, while this script makes the generated
# matrix directly executable and preserves row-level EXTRA_ENV such as synthetic
# replay settings.
#
# Usage:
#   cd benchmarking/inference
#   python scripts/compile_sweep.py --scope synthetic
#   HOST_FILTER=target_a PY=/path/to/vllm/python \
#     bash scripts/bench_orchestrator.sh --jobs scripts/bench_jobs.txt
#
# Environment:
#   HOST_FILTER          optional logical host filter matching column 1
#   OUT_ROOT             default: results/sweeps
#   PY                   default: python3
#   MIN_NREQ_PER_CONC    default: 100
#   DRY_RUN=1            print commands without launching servers
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

JOBS_FILE="${ROOT}/scripts/bench_jobs.txt"
HOST_FILTER="${HOST_FILTER:-}"
OUT_ROOT="${OUT_ROOT:-${ROOT}/results/sweeps}"
PY="${PY:-python3}"
MIN_NREQ_PER_CONC="${MIN_NREQ_PER_CONC:-100}"
DRY_RUN="${DRY_RUN:-0}"
LIMIT="${LIMIT:-0}"

usage() {
    sed -n '1,22p' "$0" | sed 's/^# \{0,1\}//'
}

while [[ $# -gt 0 ]]; do
    case "$1" in
        --jobs) JOBS_FILE="$2"; shift 2 ;;
        --host) HOST_FILTER="$2"; shift 2 ;;
        --out-root) OUT_ROOT="$2"; shift 2 ;;
        --python) PY="$2"; shift 2 ;;
        --min-nreq-per-conc) MIN_NREQ_PER_CONC="$2"; shift 2 ;;
        --limit) LIMIT="$2"; shift 2 ;;
        --dry-run) DRY_RUN=1; shift ;;
        -h|--help) usage; exit 0 ;;
        *) echo "Unknown flag: $1" >&2; usage >&2; exit 2 ;;
    esac
done

if [[ ! -f "$JOBS_FILE" ]]; then
    echo "bench jobs file not found: $JOBS_FILE" >&2
    echo "Run: python scripts/compile_sweep.py --scope synthetic" >&2
    exit 2
fi

mkdir -p "$OUT_ROOT"

rows_seen=0
rows_run=0
rows_skipped=0

run_row() {
    local host="$1"
    local model_path="$2"
    local tp="$3"
    local short="$4"
    local mode="$5"
    local backend="$6"
    local max_len="$7"
    local gpu_mem="$8"
    local concs="$9"
    local profiles="${10}"
    local extra_env="${11:-}"

    local launcher
    case "${backend}:${mode}" in
        vllm:single) launcher="${SCRIPT_DIR}/sweep_all_profiles.sh" ;;
        vllm:multi) launcher="${SCRIPT_DIR}/sweep_multiturn_profiles.sh" ;;
        sglang:single) launcher="${SCRIPT_DIR}/sweep_all_profiles_sglang.sh" ;;
        sglang:multi) launcher="${SCRIPT_DIR}/sweep_multiturn_profiles_sglang.sh" ;;
        *)
            echo "[skip] unsupported backend/mode: ${backend}/${mode} for ${host} ${short}" >&2
            return 0
            ;;
    esac

    local out_dir="${OUT_ROOT}/${host}_${short}_tp${tp}_${backend}"
    echo "[run] ${host} ${short} tp=${tp} backend=${backend} mode=${mode} profiles=${profiles} concs=${concs}"
    echo "      out=${out_dir}"

    if [[ "$DRY_RUN" == "1" ]]; then
        echo "      env ${extra_env} bash ${launcher} ${model_path} ${tp} ${short} ${backend} ${out_dir} ${PY} ${gpu_mem} ${max_len} '${concs}' '${profiles}' ${MIN_NREQ_PER_CONC}"
        return 0
    fi

    (
        cd "$ROOT"
        if [[ -n "$extra_env" ]]; then
            # bench_jobs.txt is generated from the trusted local sweep manifest.
            # eval is used here so PATH=$PATH-style entries in the manifest expand.
            eval "export ${extra_env}"
        fi
        bash "$launcher" \
            "$model_path" \
            "$tp" \
            "$short" \
            "$backend" \
            "$out_dir" \
            "$PY" \
            "$gpu_mem" \
            "$max_len" \
            "$concs" \
            "$profiles" \
            "$MIN_NREQ_PER_CONC"
    )
}

while IFS= read -r line || [[ -n "$line" ]]; do
    [[ -z "$line" || "$line" == \#* ]] && continue
    IFS='|' read -r host model_path tp short mode backend max_len gpu_mem concs profiles extra_env <<<"$line"
    rows_seen=$((rows_seen + 1))

    if [[ -n "$HOST_FILTER" && "$host" != "$HOST_FILTER" ]]; then
        rows_skipped=$((rows_skipped + 1))
        continue
    fi
    if [[ "$LIMIT" != "0" && "$rows_run" -ge "$LIMIT" ]]; then
        rows_skipped=$((rows_skipped + 1))
        continue
    fi

    run_row "$host" "$model_path" "$tp" "$short" "$mode" "$backend" "$max_len" "$gpu_mem" "$concs" "$profiles" "$extra_env"
    rows_run=$((rows_run + 1))
done < "$JOBS_FILE"

echo "[done] rows_seen=${rows_seen} rows_run=${rows_run} rows_skipped=${rows_skipped}"
